{
  "implementation": "def solve(case):
    # Validate required top-level fields
    required = ['initial_state', 'max_steps', 'tool_observations', 'transitions']
    for key in required:
        if key not in case:
            raise ValueError(f"Missing required field: {key}")

    state = case['initial_state']
    max_steps = case['max_steps']
    tool_obs = case['tool_observations']
    transitions = case['transitions']

    trace = []
    step = 1

    while step <= max_steps:
        if state not in transitions:
            raise ValueError(f"State '{state}' not in transitions")
        node = transitions[state]
        if 'kind' not in node:
            raise ValueError(f"Transition for state '{state}' missing 'kind'")
        if node['kind'] == 'final':
            if 'value' not in node:
                raise ValueError(f"Final state '{state}' missing 'value'")
            return {
                "status": "completed",
                "final": node['value'],
                "trace": trace
            }
        elif node['kind'] == 'action':
            if 'action' not in node:
                raise ValueError(f"Action state '{state}' missing 'action'")
            action = node['action']
            # Determine observation
            observation = tool_obs.get(action)
            if observation is None:
                observation = "invalid-action"
                next_state = node.get('default_next', state)
            else:
                next_by_obs = node.get('next_by_observation', {})
                next_state = next_by_obs.get(observation, node.get('default_next', state))
            trace.append({
                "step": step,
                "action": action,
                "observation": observation,
                "state": next_state
            })
            state = next_state
            step += 1
        else:
            raise ValueError(f"Unknown kind '{node['kind']}' in state '{state}'")

    # Exceeded max steps without reaching a final state
    return {
        "status": "max_steps_exceeded",
        "final": None,
        "trace": trace
    }"
}
